--
-- Swaps against the pool. Signed amounts are from the pool's side.
-- Grain: one row per Swap event
--
-- Columns:
--   contract_address varbinary: renamed from `address`
--   evt_tx_hash varbinary: renamed from `tx_hash`
--   evt_index bigint: renamed from `log_index`
--   evt_block_time timestamp: renamed from `block_timestamp`
--   evt_block_date date: the UTC date of `block_timestamp`
--   evt_block_number bigint: renamed from `block_number`
--   evt_block_hash varbinary: renamed from `block_hash`
--   amount0 int256: Token0 delta, signed.
--   amount0_raw varchar: the exact decimal text of `amount0`
--   liquidity uint256: In-range liquidity after the swap.
--   liquidity_raw varchar: the exact decimal text of `liquidity`
