--   tick bigint: Tick after the swap.
--   fee bigint: Pool fee in hundredths of a bip.
--   deadline uint256: Unix deadline.
--   offset bigint
SELECT
    from_hex(substr(address, 3)) AS contract_address,
    from_hex(substr(tx_hash, 3)) AS evt_tx_hash,
    cast(log_index as bigint) AS evt_index,
    cast(from_unixtime(block_timestamp, 'UTC') as timestamp) AS evt_block_time,
    cast(from_unixtime(block_timestamp, 'UTC') as date) AS evt_block_date,
    cast(block_number as bigint) AS evt_block_number,
    from_hex(substr(block_hash, 3)) AS evt_block_hash,
    cast("amount0" as int256) AS "amount0",
    "amount0" AS "amount0_raw",
    cast("liquidity" as uint256) AS "liquidity",
    "liquidity" AS "liquidity_raw",
    cast("delta" as int256) AS "delta",
    "delta" AS "delta_raw",
    cast("sqrtPriceX96" as uint256) AS "sqrtPriceX96",
    "sqrtPriceX96" AS "sqrtPriceX96_raw",
    cast("tick" as bigint) AS "tick",
    cast("fee" as bigint) AS "fee",
    cast("deadline" as uint256) AS "deadline",
    cast("offset" as bigint) AS "offset"
FROM dune.fixture_ns.pool__swap
